"use client";
/* Router, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Router(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("router"); }, []);
  return React.createElement("piix-pal", { "pal": "router", ...piixAttrs(props) });
}

export default Router;
